/**
 * 《非遗读本》中国非遗项目数据
 * 数据来源：非遗读本_修订版(2).docx 第2-7章
 * 数据范围：24个中国项目（华县皮影戏为完整Demo，其余23个为轻量预览）
 *
 * 注意：
 * - 所有页面必须从本文件读取项目，不允许在组件中重复硬编码
 * - demoDepth: "full"  → 华县皮影戏，拥有完整详情/标签切换/视频
 * - demoDepth: "preview" → 其余项目，仅轻量图文介绍
 */

export type DemoDepth = "preview" | "full";

export type HeritageDomain =
  | "口头传统"
  | "表演艺术"
  | "节庆仪式"
  | "自然知识"
  | "传统手工艺";

export interface HeritageLocation {
  provinceCode: string;
  provinceName: string;
  cityName?: string;
  districtName?: string;
  displayName: string;
  isPrimary?: boolean;
}

export interface VideoChapter {
  /** 章节时间（秒） */
  time: number;
  /** 章节标题 */
  label: string;
}

export interface VideoInfo {
  /** 视频标题 */
  title: string;
  /** 副标题 */
  subtitle: string;
  /** 视频文件路径 */
  src: string;
  /** 封面图路径 */
  poster: string;
  /** 视频时长（秒） */
  duration: number;
  /** 视频章节列表 */
  chapters: VideoChapter[];
  /** 视频介绍 */
  description: string;
  /** 关键知识问题 */
  knowledgeQuestions: string[];
  /** 相关内容列表 */
  relatedContent: { title: string; subtitle: string; duration: string; thumbnail: string }[];
}

export interface HeritageProject {
  id: string;
  name: string;
  shortName?: string;

  domain: HeritageDomain;
  category: string;
  level?: string;

  locations: HeritageLocation[];

  summary: string;
  briefIntroduction: string;
  keyFeatures: string[];

  coverImage: string;
  heroImage?: string;

  bookChapter?: string;
  bookSection?: string;
  bookPage?: string;

  demoDepth: DemoDepth;
  hasVideo: boolean;

  detailRoute?: string;
  videoRoute?: string;

  /** 全国性项目标记：true 时不在每个省生成重复定位点 */
  isNationwide?: boolean;
  /** 跨省项目标记：在多个省显示关联 */
  isCrossProvince?: boolean;

  // 以下字段为完整详情页（demoDepth = "full"）提供更丰富的结构化内容
  /** 列入时间，如“2011年” */
  inscribedYear?: string;
  /** 代表地区 */
  representativeRegion?: string;
  /** 历史源流 */
  history?: string;
  /** 地理分布说明 */
  distributionInfo?: string;
  /** 表演特色 */
  performanceFeatures?: string[];
  /** 文化价值 */
  culturalValue?: string;
  /** 制作技艺步骤（名称 + 说明） */
  craftSteps?: { name: string; description: string }[];
  /** 视频信息（hasVideo=true 时必填） */
  videoInfo?: VideoInfo;
}

