    briefIntroduction: "四季生产调是流传于云南红河哈尼族地区的传统古歌，是山区梯田生产技术及其礼仪禁忌的百科大典。全歌分引子、冬季、春季、夏季、秋季五大单元，按季节顺序讲述梯田耕作的程序与技术要领，以及相应的天文历法、物候变化、节庆祭典和人生礼仪知识。它体系严整、通俗易懂、可诵可唱，语言生动活泼、朴素幽默，贴近生产生活，千百年来在哈尼山寨口传心授，指导着梯田稻作的春播秋收。四季生产调见证了哈尼族梯田稻作文明的变迁历程，对社会伦理规范与梯田农业研究都具有重要价值。2006年列入第一批国家级非物质文化遗产名录。",
