    briefIntroduction: "端午节为农历五月初五，是我国重要的传统节日，别称多达二十余个，如端阳节、重午节、龙舟节、浴兰节等。“端”有初始之意，五月为午月，端五渐演变为端午。其起源说法众多，以纪念屈原投汨罗江之说影响最广，此外还有纪念伍子胥、孝女曹娥、古越民族龙图腾祭祀、恶日驱邪、夏至等诸说。端午习俗丰富多彩：赛龙舟、吃粽子流传最广，另有挂艾草菖蒲、佩香囊、系五彩丝、饮雄黄酒、沐兰汤、采药、避五毒、斗草、跳钟馗、女儿回娘家躲午等，兼具卫生防疫、祈福纳吉与娱乐竞技功能。两千多年来端午节深植于中华各民族的岁时生活，2006年列入第一批国家级非物质文化遗产名录，2009年入选联合国教科文组织人类非物质文化遗产代表作名录。",
