    briefIntroduction: "厂甸庙会是北京春节期间的传统民俗活动，历时四百多年，以琉璃厂为核心地带。它始于民间庙市，明清之际因内城灯市外移而渐成规模，以书画古董、文房四宝荟萃著称，被誉为“文市”，又融特色小吃、儿童玩具、花会表演于一体，雅俗相济、商娱相融。清乾隆年间已“百货云集，灯屏琉璃”，民国时期游人如织，1964年起一度停办，2001年恢复举办。大糖葫芦、风车、空竹、老天桥绝活等是其标志性风物。厂甸庙会是展示京味文化与宣南文化的窗口，与南京夫子庙、上海城隍庙等并称中国著名庙会。2006年列入第一批国家级非物质文化遗产名录。",
