    briefIntroduction: "土族盘绣流传于青海省互助土族自治县，是土族独有的刺绣工艺，其起源与土族服饰装饰传统相伴而生。盘绣不用棚架，绣娘双手操针，一根线盘绕、一根线钉固，以“两针两线”的独特针法层层盘结，绣品呈现出厚实的浮雕质感。纹样多为富贵不断头、云纹、太极图、花鸟等吉祥图案，多用于衣领、袖头、腰带、荷包等处，配色艳丽浓烈，经久耐磨。盘绣凝结着土族妇女的勤劳与智慧，是土族文化的活态载体，一针一线间传承着民族记忆。2006年列入第一批国家级非物质文化遗产名录。",
